architecture.h4_f:
|
msg = CBOR{v:1, text, reply_to, send_at}
ct = AES-GCM-256- کوډ شوی (k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
|
pt = CBOR{v:1, text, reply_to?, thread_id?, ذکرونه؟, sent_at}
ct = AES-GCM-256- کوډ کول(د کوټې کیلي، نونس، pt، aad=hex(room_id))
تار = CBOR{
  v: 1،
  ciphertext: hex(ct)، // متغیر اوږدوالی
  نه: هیکس (12 ب)،
  لیږونکی_سیډو: هیکس (16 ب)،
  لیږل شوی: یونکس_ ایم ایس
}

cryptoWire.h5_f:
|
بهر = CBOR{
  سرچینه_نوډ: hex32,
  هدف_کاروونکی: int64،
  داخلی_سیفر متن: بایټ،
  inner_nonce: بایټ،
  لیږل شوی: یونکس_ ایم ایس
}
sig = Ed25519-نښه
POST /فیډریشن/ډیلیور { لفافه: بهرنۍ، نښه: hex64 }

auth.h1_f:
|
POST /api/authentication/register
  { کارن نوم، پټنوم، x25519_public_key، display_name، تلیفون؟، بریښنالیک؟، avatar_emoji }

ځواب 201 جوړ شوی:
  { access_token , refresh_token , user_id , username , ... }

auth.h3_f:
access_token payload:
  { فرعي: user_id، jti: device_id، ټایپ: "لاسرسی"، exp: اوس + 15 دقیقې }
refresh_token payload:
  { فرعي: user_id، jti: device_id، ټایپ: "ریفریش"، exp: اوس + 30d }

HS256-د .env څخه د نوډ د 64-بایټ راز سره لاسلیک شوی

auth.h7_f:
|
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR پېلوډ = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → نوې وسیله ثبت شوې؛ JWTs بیرته راستانه شول.

rooms.h6_f:
لیږونکی_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
ciphertext = AES-GCM- کوډ شوی

د فین آوټ چوکاټ: {ډول:"م"، کوټه، پیغام:{id، ct، nonce، sender_pseudo, sent_at} }

files.h2_f:
|
init POST /api/files/resumable/init {د فایل نوم، اندازه، chunk_size_hint}
            ← {upload_id, chunk_size}
ټوټه PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← ۲۰۴
نهایی کول POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL په نامکمل وخت کې: 24 ساعته

presence.h1_f:
|
پیرودونکي: په لومړي کیسټروک کې → لیږل {ډول:"t"، حالت:"پیل"}
         نور د 3s لپاره نه لیږل کیږي پرته لدې چې حالت بدل شي
         د وروستي کیسټروک وروسته 10 ثانیې → لیږل {ډول:"t"، حالت:"بند"}
ترلاسه کونکی: د وروستي "پیل" وروسته 10 s اتوماتیک ودرول که چیرې "بند" نه وي راغلی

calls.h1_f:
|
POST /api/calls/{room_id}/start {ویډیو، آډیو} → call_id
WS خپرونه {ډول:"c"، ډول:"بلنه"، call_id}
WS خپرونه {ډول:"c"، ډول:"وړاندیز"، sdp}
WS خپرونه {ډول:"c"، ډول:"ځواب"، sdp}
WS خپرونه {ډول:"c"، ډول:"کانديد"، ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
لفافه = {
  سرچینه_نوډ: hex32,
  هدف_کاروونکی: int64,
  داخلی_سیفر متن: بایټ،
  داخلي_نانس : بايټونه
  لیږل شوی: یونکس_ ایم ایس،
}
sig = Ed25519Sign(سرچینه_priv, CBOR(لفافه))
POST /فدراسیون/تولید {لفافه، لاسلیک }

gossip.h3_f:
|
اعلان = {پبکی، پای ټکی، اعلان شوی_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(اعلان))
د ګپ شپ پیلډ: [...، {اعلان، نښه}، ...]

ترلاسه کوونکی: د ad.pubkey په وړاندې لاسلیک تایید کړئ → پلورنځي IF OK
اضافي: د PoW 2^18 مخکښ صفر په {pubkey, endpoint}

push.h4_f:
|
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
ویب SW: self.addEventListener('push', e => پټول(e.data))

controller.h2_f:
|
وسیله = نښه_وسیله
input = سرچینه ونه، keys/release.key
ښکاره = {
  نسخه: "0.1.0"
  build_at: unix_ms,
  دوتنې: [{path, sha256, size}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(ښکاره))
output = INTEGRITY.sig.json = {ښکاره، لاسلیک شوی_بای: pub_hex، sig: sig_hex}

bots.h1_f:
|
جوړ کړئ: POST /api/bots {کارن نوم، display_name، code}
          → {bot_id, token, pubkey}
چلول: په پروسه کې (کورټین دننه نوډ)
      OR بهرنۍ (اوږده ټولپوښتنه /api/bots/{id}/updates, token-auth'd)
پیغام: {متن، لاسلیک: Ed25519-Sign(bot_priv, canonical_msg)}

